public class Main {
    public static void main(String[] args) {
        Greeter a = new Alice();
        Greeter b = new Bob();
        a.greet();
        a.farewell();
        b.greet();
        b.farewell();
    }
}

interface Greeter {
    void greet();

    default void farewell() {
        System.out.println("Bye");
    }
}

class Alice implements Greeter {
    public void greet() {
        System.out.println("Hi from Alice");
    }
}

class Bob implements Greeter {
    public void greet() {
        System.out.println("Hi from Bob");
    }
}
